<?php
require_once __DIR__ . '/includes_excel_data.php';
ensureExcelTables($pdo);
if (session_status() !== PHP_SESSION_ACTIVE) session_start();
if (empty($_SESSION['benefit_usage_csrf'])) $_SESSION['benefit_usage_csrf'] = bin2hex(random_bytes(32));
$csrf = $_SESSION['benefit_usage_csrf'];
$notice=''; $noticeType='success'; $postSavedArea=null; $postSavedFY=null;
function usage_fiscal_year(DateTimeImmutable $dt): int { $y=(int)$dt->format('Y'); return $y + ((int)$dt->format('n')>=10 ? 544 : 543); }
if ($_SERVER['REQUEST_METHOD']==='POST') {
    $token=(string)($_POST['csrf_token']??'');
    if (!hash_equals($csrf,$token)) { $notice='แบบฟอร์มหมดอายุหรือไม่ถูกต้อง กรุณาโหลดหน้าใหม่'; $noticeType='error'; }
    else {
        $memberNo=trim((string)($_POST['member_number']??''));
        $usedAtRaw=trim((string)($_POST['used_at']??''));
        $area=(string)($_POST['benefit_area']??'museum');
        $benefitType=trim((string)($_POST['benefit_type']??''));
        $location=trim((string)($_POST['location']??''));
        $memberLevel=trim((string)($_POST['member_level']??''));
        $notes=trim((string)($_POST['notes']??''));
        $dt=DateTimeImmutable::createFromFormat('Y-m-d\TH:i',$usedAtRaw);
        $dateErrors=DateTimeImmutable::getLastErrors();
        if (!$dt || ($dateErrors && ($dateErrors['warning_count']||$dateErrors['error_count'])) || !in_array($area,['museum','lounge'],true) || $memberNo==='' || $benefitType==='' || $location==='') {
            $notice='กรุณากรอกรหัสสมาชิก วันเวลา ประเภทสิทธิ์ และสถานที่ให้ครบถ้วน'; $noticeType='error';
        } else {
            $memberStmt=$pdo->prepare("SELECT `หมายเลขสมาชิก` member_no, COALESCE(NULLIF(`รายชื่อลูกค้า`,''),NULLIF(`ชื่อผู้รับวารสาร`,''),'') member_name, COALESCE(NULLIF(`กลุ่มลูกค้า`,''),'') member_type FROM excel_member_records WHERE TRIM(`หมายเลขสมาชิก`)=? ORDER BY id DESC LIMIT 1");
            $memberStmt->execute([$memberNo]); $member=$memberStmt->fetch(PDO::FETCH_ASSOC);
            if (!$member) { $notice='ไม่พบรหัสสมาชิกนี้ในข้อมูล Excel ที่นำเข้า กรุณาตรวจสอบรหัสสมาชิกก่อนบันทึก'; $noticeType='error'; }
            else {
                $dt=$dt->setTimezone(new DateTimeZone(date_default_timezone_get()));
                $insert=$pdo->prepare("INSERT INTO benefit_usage_records (member_number,member_name,benefit_area,used_at,fiscal_year,benefit_type,location,member_type,member_level,notes) VALUES (?,?,?,?,?,?,?,?,?,?)");
                $insert->execute([$memberNo,($member['member_name']?:$memberNo),$area,$dt->format('Y-m-d H:i:s'),usage_fiscal_year($dt),$benefitType,$location,$member['member_type'],$memberLevel!==''?$memberLevel:null,$notes!==''?$notes:null]);
                $notice='บันทึกการใช้สิทธิ์เรียบร้อยแล้ว'; $noticeType='success';
                $postSavedArea=$area; $postSavedFY=usage_fiscal_year($dt);
                $_POST=[];
            }
        }
    }
}
$areaFilter=(string)($_GET['area']??($postSavedArea??'museum')); if(!in_array($areaFilter,['museum','lounge'],true))$areaFilter='museum';
$formArea=(string)($_POST['benefit_area']??$areaFilter); if(!in_array($formArea,['museum','lounge'],true))$formArea=$areaFilter;
$defaultFY=latest_excel_fiscal_year($pdo); $fy=(int)($_GET['fy']??($postSavedFY??$defaultFY)); if($fy<2500||$fy>2700)$fy=$defaultFY;
$st=$pdo->prepare("SELECT COUNT(*) total, COUNT(DISTINCT member_number) members, COUNT(*) / NULLIF(COUNT(DISTINCT member_number),0) avg_per_member, COUNT(DISTINCT DATE(used_at)) usage_days FROM benefit_usage_records WHERE benefit_area=? AND fiscal_year=?");$st->execute([$areaFilter,$fy]);$summary=$st->fetch(PDO::FETCH_ASSOC)?:[];
$st=$pdo->prepare("SELECT member_number,MAX(member_name) member_name,COUNT(*) use_count,COUNT(DISTINCT benefit_type) type_count,GROUP_CONCAT(DISTINCT benefit_type ORDER BY benefit_type SEPARATOR ', ') benefit_types,GROUP_CONCAT(DISTINCT location ORDER BY location SEPARATOR ', ') locations,MAX(member_type) member_type,MAX(member_level) member_level,MAX(used_at) last_used FROM benefit_usage_records WHERE benefit_area=? AND fiscal_year=? GROUP BY member_number ORDER BY use_count DESC,last_used DESC LIMIT 100");$st->execute([$areaFilter,$fy]);$memberSummary=$st->fetchAll(PDO::FETCH_ASSOC);
$st=$pdo->prepare("SELECT used_at,member_number,member_name,benefit_type,location,member_type,member_level,notes FROM benefit_usage_records WHERE benefit_area=? AND fiscal_year=? ORDER BY used_at DESC,id DESC LIMIT 100");$st->execute([$areaFilter,$fy]);$recent=$st->fetchAll(PDO::FETCH_ASSOC);
$areas=['museum'=>'พิพิธภัณฑ์','lounge'=>'Member Lounge'];
